printf 'import gzip, os, shutil\nos.makedirs('\''logs/archive'\'', exist_ok=True)\nfor name in sorted(os.listdir('\''logs'\'')):\n    path = os.path.join('\''logs'\'', name)\n    if name.endswith('\''.log'\'') and os.path.isfile(path) and os.path.getsize(path) > 1000:\n        with open(path, '\''rb'\'') as src, gzip.open(path.replace('\''logs/'\'', '\''logs/archive/'\'') + '\''.gz'\'', '\''wb'\'') as dst:\n            shutil.copyfileobj(src, dst)\n        os.remove(path)\n' > archive_logs.py
